export function createProviderRunners(context){
  async function consumeSSE(response,onData){if(!response.ok){let text=await response.text();try{text=JSON.parse(text).error?.message||text}catch{}throw Error(`${response.status}: ${text.slice(0,300)}`)}if(!response.body)throw Error('المتصفح لا يدعم تدفق الاستجابة');let reader=response.body.getReader(),decoder=new TextDecoder(),buffer='';function parse(data){try{return JSON.parse(data)}catch{return null}}while(true){let {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let blocks=buffer.split(/\r?\n\r?\n/);buffer=blocks.pop();for(let block of blocks){let data=block.split(/\r?\n/).filter(l=>l.startsWith('data:')).map(l=>l.slice(5).trimStart()).join('\n');if(data&&data!=='[DONE]'){let event=parse(data);if(event)onData(event)}}}if(buffer.trim()){let data=buffer.split(/\r?\n/).find(l=>l.startsWith('data:'));if(data){let event=parse(data.slice(5).trimStart());if(event)onData(event)}}}
  async function runCompatible(p,history,output){const {chat,controller,effort,keyFor,commonMessages,effectiveSystem,TOOL_GUIDE,projectContext,isText,fileContext,processToolCalls,refreshLastMessage}=context;let key=keyFor(p);if(!key&&p.type!=='compatible')throw Error('أضف مفتاح API من الإعدادات أولاً');let headers={'Content-Type':'application/json'};if(key)headers.Authorization='Bearer '+key;if(p.type==='openrouter'){headers['HTTP-Referer']=location.origin==='null'?'https://localhost':location.origin;headers['X-OpenRouter-Title']='AiWay'}let body={model:p.model,messages:commonMessages(history),stream:true};if(p.type==='openrouter'&&effort!=='off')body.reasoning={effort};else if(p.type==='compatible'&&effort!=='off')body.reasoning_effort=effort;let res=await fetch(p.url.replace(/\/+$/,'')+'/chat/completions',{method:'POST',headers,body:JSON.stringify(body),signal:controller.signal});await consumeSSE(res,data=>{if(data.error)throw Error(data.error.message||'خطأ من المزود');let d=data.choices?.[0]?.delta;if(!d)return;let reason=d.reasoning||d.reasoning_content||d.reasoning_details?.map(x=>x.text||'').join('')||'';if(reason)output.reason+=reason;if(typeof d.content==='string'){output.text+=d.content;processToolCalls(output)}if(chat.messages.at(-1)===output)refreshLastMessage()})}
  async function runGemini(p,history,output){const {chat,controller,effort,keyFor,commonMessages,effectiveSystem,TOOL_GUIDE,projectContext,isText,fileContext,processToolCalls,refreshLastMessage}=context;let key=keyFor(p);if(!key)throw Error('أضف مفتاح Gemini API من الإعدادات أولاً');let contents=history.map(m=>{let parts=[{text:(m.text||'')+(m.role==='user'?(m.attachments||[]).filter(isText).map(fileContext).join(''):'')}];if(m.role==='user')for(let f of m.attachments||[])if(f.mime.startsWith('image/')||f.mime==='application/pdf')parts.push({inlineData:{mimeType:f.mime,data:f.data.split(',')[1]}});return{role:m.role==='assistant'?'model':'user',parts}});let body={systemInstruction:{parts:[{text:effectiveSystem()+TOOL_GUIDE+projectContext()}]},contents,generationConfig:{}};if(effort!=='off'){body.generationConfig.thinkingConfig={includeThoughts:true};if(p.model.includes('2.5'))body.generationConfig.thinkingConfig.thinkingBudget=({low:512,medium:2048,high:8192})[effort];else body.generationConfig.thinkingConfig.thinkingLevel=effort.toUpperCase()}else if(p.model.includes('2.5-flash'))body.generationConfig.thinkingConfig={thinkingBudget:0};let model=p.model.replace(/^models\//,''),url=p.url.replace(/\/+$/,'')+'/models/'+encodeURIComponent(model)+':streamGenerateContent?alt=sse',headers={'Content-Type':'application/json','x-goog-api-key':key};let res=await fetch(url,{method:'POST',headers,body:JSON.stringify(body),signal:controller.signal});await consumeSSE(res,data=>{if(data.error)throw Error(data.error.message||'خطأ من Gemini');for(let part of data.candidates?.[0]?.content?.parts||[]){if(part.text){if(part.thought)output.reason+=part.text;else{output.text+=part.text;processToolCalls(output)}}}if(chat.messages.at(-1)===output)refreshLastMessage()})}
  async function runOpenCode(p,history,output){const {chat,controller,effort,keyFor,commonMessages,effectiveSystem,TOOL_GUIDE,projectContext,isText,fileContext,processToolCalls,refreshLastMessage}=context;let current=chat,base=p.url.replace(/\/+$/,'');let key=keyFor(p),headers={'Content-Type':'application/json'};if(key)headers.Authorization='Basic '+btoa('opencode:'+key);current.opencodeSessions ||= {};let sessionId=current.opencodeSessions[p.id];if(!sessionId){let create=await fetch(base+'/session',{method:'POST',headers,body:JSON.stringify({title:current.title}),signal:controller.signal});if(!create.ok)throw Error('تعذر إنشاء جلسة OpenCode: '+create.status);sessionId=(await create.json()).id;current.opencodeSessions[p.id]=sessionId}let last=history.at(-1);let parts=[{type:'text',text:last.text+(last.attachments||[]).filter(isText).map(fileContext).join('')}];for(let f of last.attachments||[])if(f.mime.startsWith('image/'))parts.push({type:'file',mime:f.mime,url:f.data,filename:f.name});let body={parts,system:effectiveSystem()+TOOL_GUIDE+projectContext()};if(p.model?.includes('/')){let [providerID,...rest]=p.model.split('/');body.model={providerID,modelID:rest.join('/')}}let res=await fetch(base+'/session/'+encodeURIComponent(sessionId)+'/message',{method:'POST',headers,body:JSON.stringify(body),signal:controller.signal});if(!res.ok)throw Error('OpenCode: '+res.status+' '+(await res.text()).slice(0,200));let data=await res.json();output.text=(data.parts||[]).filter(x=>x.type==='text').map(x=>x.text).join('\n');output.reason=(data.parts||[]).filter(x=>x.type==='reasoning').map(x=>x.text).join('\n');processToolCalls(output);if(chat.messages.at(-1)===output)refreshLastMessage()}
return {runCompatible,runGemini,runOpenCode};
}
